INSERT INTO material_translations (material_id, locale, title, description, body) VALUES ('0035223a-2c23-4810-b8b5-f44088a0d4f5','ro','Atmosfera și caracteristicile climatice — galerie foto','Galerie foto pentru lecția Atmosfera și caracteristicile climatice: forma și structura atmosferei, norii și fenomenele meteorologice, stratul de ozon, curenții-jet, aurorele, circulația generală, hărțile de temperatură și precipitații, brizele și musonii.','{"captions":["Forma atmosferei — învelișul de aer, mai bombat la Ecuator și mai subțire la poli","Structura verticală a atmosferei și variația temperaturii cu altitudinea (de la troposferă la exosferă)","Tipuri de nori: stratus, stratocumulus, cumulus, altocumulus, altostratus, cirrus, cirrocumulus, cumulonimbus","Fenomene din troposferă: ploi, uragan, tornadă, fulger, viscol, îngheț","Filtrarea radiațiilor ultraviolete (UV) de către stratul de ozon din stratosferă","Curenții-jet polari și tropicali, la limita superioară a troposferei","Aurore polare văzute din spațiu, deasupra zonei polare","Exosfera și centurile de radiații Van Allen (interioară și exterioară)","Bilanțul radiativ (Q): componentele radiației solare și terestre","Circulația generală a atmosferei: calmul ecuatorial, alizeele, vânturile de vest și vânturile polare","Temperaturi medii anuale pe glob — izoterme","Precipitații medii anuale pe glob — izohiete","Brizele: briza de zi (dinspre mare) și briza de noapte (dinspre uscat)","Musonii din Asia: musonul de vară (umed) și musonul de iarnă (uscat)"]}');
